      "action": "merge_pr",
      "workspace_base": 0,
      "config": {
        "repository": "takahirox/gitweave",
        "publish_node": "publish"
      }
    }
  },
  "flow": [
    "implement",
    {
      "if": {
        "condition": {
          "path": "/0/data/status",
          "equals": "ready"
        },
        "then": [
          "publish",
          "review",
          {
            "loop": {
              "flow": [
                {
                  "if": {
                    "condition": {
                      "path": "/0/data/status",
                      "equals": "changes_requested"
                    },
                    "then": [
                      "fix",
                      {
                        "if": {
                          "condition": {
                            "path": "/0/data/status",
                            "equals": "ready"
                          },
                          "then": [
                            "publish",
                            "review"
                          ],
