                        }
                      }
                    ],
                    "else": []
                  }
                }
              ],
              "while": {
                "path": "/0/data/status",
                "equals": "changes_requested"
              }
            }
          }
        ],
        "else": []
      }
    },
    {
      "if": {
        "condition": {
          "path": "/0/data/status",
          "equals": "approved"
        },
